# -*- coding: utf-8 -*-
"""DEVELOPMENT set for the incident-state fix. Authored after the frozen challenge set and the baseline run, with DIFFERENT wording, to give the implementation something to be tuned on
without tuning on the challenge cases. It is not evidence of anything: it is a tuning aid written by the engine's author. Same schema as author_incident.py."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(HERE, "author_incident.py"), encoding="utf-8").read()
ns = {"__file__": os.path.join(HERE, "author_incident.py"), "__name__": "author_incident_base"}
exec(compile(src[:src.index("# ---- A. completed")], "author_incident.py(head)", "exec"), ns)
c, C = ns["c"], ns["C"]; P, Q, R, S, T, U, V, W, X = ns["P"], ns["Q"], ns["R"], ns["S"], ns["T"], ns["U"], ns["V"], ns["W"], ns["X"]
UP, UC, UN, TP, SC, UD, PU, NI = ns["UP"], ns["UC"], ns["UN"], ns["TP"], ns["SC"], ns["UD"], ns["PU"], ns["NI"]; HG, HI = ns["HG"], ns["HI"]
c("D01", P, "Two days ago I remitted 75,000 to their firm and today they asked for an additional charge to release the profit.", "ESCALATE", UP, "USER", "dev", ok=["ESCALATE", "ASK"], sev="critical")
