c("D06", P, "मैंने अनजान व्यक्ति को 10,000 रुपये दे दिए।", "ESCALATE", UP, "USER", "dev", lang=HI, ok=["ESCALATE", "ASK"], sev="critical")
c("D07", U, "I gave my OTP to the person who said he was my bank manager.", "ESCALATE", UC, "USER", "dev", sev="critical")
