c("D18", R, "She claims she has paid the full amount already.", "NORMAL", SC, "CLAIM", "dev", sev="high")
c("D19", R, "The caller said that I had paid yesterday.", "NORMAL", SC, "CLAIM", "dev", sev="high")
c("D20", R, "Humne nahi, unhone bheja tha.", "NORMAL", TP, "THIRD", "dev", lang=HG, sev="high")
c("D21", S, "I have not transferred a rupee.", "NORMAL", UD, "USER", "dev", sev="critical")
