ids = [x["id"] for x in C]; assert len(ids) == len(set(ids))
with open(os.path.join(HERE, "cases_incident_dev.jsonl"), "w", encoding="utf-8") as f:
    for x in C: f.write(json.dumps(x, ensure_ascii=False) + "\n")
print(len(C))
